#include "unique-score-sheet.h"

std::optional<std::array<int,3>> charm::v1n7::yacht::summarize_unique_score_sheet(const std::vector<charm::v1n7::yacht::YachtTurn>& turns){auto score_rule=[](const YachtTurn& turn)->std::optional<int>{std::array<int,7> counts{};int sum=0;for(int die:turn.dice){if(die<1||die>6)return std::nullopt;++counts[die];sum+=die;}if(turn.rule=="sum")return sum;if(turn.rule=="all-even")return std::all_of(turn.dice.begin(),turn.dice.end(),[](int d){return d%2==0;})?sum:0;if(turn.rule=="three-match")return *std::max_element(counts.begin(),counts.end())>=3?sum:0;if(turn.rule=="full-run"){std::set<int> faces(turn.dice.begin(),turn.dice.end());return faces==std::set<int>({1,2,3,4,5})||faces==std::set<int>({2,3,4,5,6})?30:0;}return std::nullopt;};std::set<std::string> rules;int total=0,zeros=0;for(const auto& turn:turns){if(!rules.insert(turn.rule).second)return std::nullopt;auto score=score_rule(turn);if(!score||total>std::numeric_limits<int>::max()-*score)return std::nullopt;total+=*score;if(*score==0)++zeros;}return std::array<int,3>{total,static_cast<int>(rules.size()),zeros};}
